mapper.sql:
FROM lectures
JOIN courses ON lectures.course_id = courses.id
JOIN users ON lectures.professor_id = users.id


        AND courses.name LIKE CONCAT('%', #{searchReq.courseName}, '%')


        AND users.name LIKE CONCAT('%', #{searchReq.professorName}, '%')


        AND lectures.year = #{searchReq.year}


        AND lectures.semester = #{searchReq.semester}


        AND courses.code = #{searchReq.courseCode}
